def pick(n):
    if n > 10:
        return "big"
    elif n > 5:
        return "mid"
    else:
        return "small"
assert [pick(20), pick(7), pick(1)] == ["big", "mid", "small"]
ran = []
if True:
    ran.append(1)
elif True:
    ran.append(2)
else:
    ran.append(3)
assert ran == [1]

class Parent:
    def greet(self):
        return "hello"
class Child(Parent):
    def greet(self):
        return super().greet() + " world"
assert Child().greet() == "hello world"
